import { analyzeUrl, hashFile, createCase, validateWorkspace, exportReport, encryptWorkspace, decryptWorkspace, TYPES, PLAYBOOKS } from './core.mjs';
import { isWorkspaceDirty, readArchiveInput, saveCiphertext, eraseCiphertext } from './vault.mjs';

const $ = selector => document.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons = {
  home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',
  file:'M14 2H5v20h14V7zm0 0v6h5M8 13h8M8 17h5',
  link:'m9 15 6-6M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 10a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-1 1',
  cases:'M3 6h7l2 3h9v12H3zM3 6V3h7l2 3h9v3',
  book:'M12 5C8 2 4 3 2 4v15c3-2 7-2 10 0 3-2 7-2 10 0V4c-3-1-7-2-10 1zm0 0v14',
  lock:'M6 10h12v11H6zm2 0V6a4 4 0 0 1 8 0v4m-4 4v3',
  shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zm-4 10 3 3 5-6',
  plus:'M12 5v14M5 12h14',
  arrow:'M5 12h14m-6-6 6 6-6 6',
  download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',
  check:'m4 12 5 5L20 6',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.shield}"/></svg>`;
const routes = [['overview','Overview','home'],['evidence','Check evidence','file'],['link','Review a link','link'],['cases','Incident cases','cases'],['library','Response library','book'],['vault','Vault & privacy','lock']];
const storageKey = 'usualcybersec-vault-v1';
let workspace = {version:1,cases:[]};
let savedSnapshot = null;
let vaultRaw = null;
let vaultChanged = false;
let storageAvailable = true;
try { vaultRaw = localStorage.getItem(storageKey); } catch { storageAvailable = false; }
let latestEvidence = null;
let lastUrl = null;
let operation = 0;
let busy = false;
let noticeTimer;
const date = value => new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
const typeLabel = type => TYPES.find(t=>t.id===type)?.label || type;
const statusLabel = status => ({open:'Open','in-progress':'In progress',resolved:'Resolved'}[status]);
const currentCase = id => workspace.cases.find(item=>item.id===id);
const dirty = () => isWorkspaceDirty(workspace, savedSnapshot) || (vaultChanged && workspace.cases.length > 0);
const external = (url, label) => `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a>`;
const heading = (title,subtitle,action='') => `<div class="page-heading"><div><h1>${title}</h1><p class="subtext">${subtitle}</p></div>${action}</div>`;
const newButton = `<a class="btn primary" href="#new">${icon('plus')}New incident</a>`;
const privacyLine = `<div class="privacy-line">${icon('lock')}Processed on your device. No upload.</div>`;
const errorBox = '<p class="error" role="alert" hidden></p>';
function notify(text, error=false) { clearTimeout(noticeTimer); const el=$('#notice'); el.textContent=text; el.hidden=false; el.classList.toggle('error-toast',error); noticeTimer=setTimeout(()=>{el.hidden=true;},6500); }
function showError(error, form) { const target=form?.querySelector('.error'); if(target){target.textContent=error.message || String(error);target.hidden=false;}else notify(error.message || String(error),true); }
function go(route) { if(location.hash===`#${route}`)render();else location.hash=route; }
function syncStatus(){ $('#storage-state').textContent=dirty()?'Unsaved session':savedSnapshot?'Vault unlocked':vaultRaw?'Saved vault locked':'Session only'; }
function commit(next){ validateWorkspace(next); workspace=next;syncStatus(); }
function updateCase(id, action){ const next=structuredClone(workspace); const item=next.cases.find(c=>c.id===id);if(!item)throw Error('This incident is no longer in the workspace.');action(item);item.updatedAt=new Date().toISOString();commit(next); }
function caseRows(items){return items.map(item=>`<a href="#case/${encodeURIComponent(item.id)}" class="case-row"><div><h3>${escape(item.title)}</h3><p>${escape(typeLabel(item.type))} · ${escape(date(item.updatedAt))}</p></div><span class="badge ${item.status==='open'?'warning':item.status==='resolved'?'':'neutral'}">${statusLabel(item.status)}</span></a>`).join('');}
function emptyCases(){return `<div class="empty">${icon('cases')}<h3>No incidents recorded</h3><p>Keep the facts, evidence, and next steps together when something feels wrong.</p><a class="text-link" href="#new">Create your first incident →</a></div>`;}

function overview(){return `${heading('Your safety workspace','A place to make sense of something suspicious.',newButton)}
  ${vaultRaw&&!savedSnapshot?'<div class="alert">An encrypted workspace is saved on this device. <a href="#vault">Unlock your vault</a> to continue those cases.</div>':''}
  <section class="hero"><div><h2>When something feels off,<br>start here.</h2><p>A suspicious video. An account that isn’t yours. A message that asks too much. Gather the facts and find your next step.</p><a href="#evidence" class="btn">Check a file ${icon('arrow')}</a></div><div class="hero-workflow"><div class="workflow-step"><span class="step-index">1</span><div><strong>Pause & verify</strong><span>Check the request through a trusted channel.</span></div></div><div class="workflow-step"><span class="step-index">2</span><div><strong>Preserve what you have</strong><span>Keep original files, messages, and context.</span></div></div><div class="workflow-step"><span class="step-index">3</span><div><strong>Take the next step</strong><span>Follow a response plan for your situation.</span></div></div></div></section>
  <div class="section-heading"><h2>A closer look</h2><span class="muted subtext">Private by design</span></div><div class="tool-list"><a class="tool-link" href="#evidence"><span class="tool-icon">${icon('file')}</span><div><h3>Preserve media evidence</h3><p>Fingerprint a file and record where it came from. Keep uncertainty visible.</p></div><span class="arrow">↗</span></a><a class="tool-link" href="#link"><span class="tool-icon">${icon('link')}</span><div><h3>Look behind a link</h3><p>Reveal the destination hostname and structural warning signs without visiting it.</p></div><span class="arrow">↗</span></a></div>
  <div class="lower-grid"><section><div class="section-heading"><h2>Your recent incidents</h2><a href="#cases" class="text-link">View all →</a></div>${workspace.cases.length?caseRows([...workspace.cases].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3)):emptyCases()}</section><aside class="note">${icon('shield')}<h3>Useful evidence. Honest limits.</h3><p>No tool can promise that every video is real or every link is safe. We help you preserve facts and act carefully.</p><a class="text-link" href="#library">Understand the methods →</a></aside></div>`;}

function evidence(){return `${heading('Check evidence','Create a fingerprint of a file, without uploading it.')}<div class="two-columns"><section class="panel">${privacyLine}<form id="hash-form"><div class="field"><label for="media-file">Original file</label><input id="media-file" name="file" type="file" required><p class="hint">Any file type · up to 100 MiB. Files are read for hashing, never opened or played.</p></div><div class="field"><label for="expected-hash">Compare with a SHA-256 fingerprint <span class="muted">(optional)</span></label><input id="expected-hash" name="expected" placeholder="64 hexadecimal characters" pattern="[a-fA-F0-9]{64}" maxlength="64" autocomplete="off" spellcheck="false"><p class="hint">Use a fingerprint from a separately trusted source.</p></div>${errorBox}<button class="btn primary" type="submit">${icon('file')}Fingerprint file</button></form><div id="hash-result">${latestEvidence?evidenceResult():''}</div></section><aside class="stack"><div class="note"><h3>What this tells you</h3><p>SHA-256 identifies the exact bytes of this copy. A matching fingerprint means the bytes match the reference.</p><h3>What it cannot tell you</h3><p>It does not detect AI generation, authenticate a person, or prove a scene happened. A re-encoded copy will have a different hash.</p></div><div><h3>Keep the original</h3><p class="subtext">The app stores a fingerprint and your notes, not the original file. Keep that file somewhere safe, with its source and context.</p><details><summary>Content Credentials</summary><p>Signed provenance can describe how media was created or edited. It does not prove a claim is true, and missing credentials do not prove a fake. This version does not verify C2PA signatures.</p>${external('https://spec.c2pa.org/specifications/specifications/2.4/security/Harms_Modelling.html','Read the C2PA limits')}</details></div></aside></div>`;}
function evidenceResult(){const e=latestEvidence.record;return `<div class="result"><span class="badge">Fingerprint created</span><h3>${escape(e.name || 'Unnamed file')}</h3><code class="digest">${e.sha256}</code><dl class="facts"><dt>Size</dt><dd>${e.size.toLocaleString()} bytes</dd><dt>Reported type</dt><dd>${escape(e.type || 'Not supplied')}</dd><dt>Hashed on this device</dt><dd>${escape(date(e.hashedAt))}</dd></dl>${latestEvidence.expected?`<p class="alert">${latestEvidence.expected.toLowerCase()===e.sha256?'The fingerprints match. This does not establish authenticity.':'The fingerprints differ. This copy does not match the supplied reference.'}</p>`:''}<form id="attach-form"><div class="field"><label for="attach-case">Add fingerprint to an incident</label><select id="attach-case" name="caseId" ${workspace.cases.length?'':'disabled'}>${workspace.cases.map(item=>`<option value="${escape(item.id)}">${escape(item.title)}</option>`).join('') || '<option>Create an incident first</option>'}</select></div><div class="field"><label for="evidence-source">Where did you obtain this file? <span class="muted">(optional URL)</span></label><input id="evidence-source" name="sourceUrl" type="url" maxlength="2048" placeholder="https://example.com/original-post"></div><div class="field"><label for="evidence-notes">Acquisition context <span class="muted">(optional)</span></label><textarea id="evidence-notes" name="notes" maxlength="10000" placeholder="When you received it, who supplied it, any edits or conversions…"></textarea></div><div class="actions"><button class="btn" ${workspace.cases.length?'':'disabled'}>Attach fingerprint</button><a class="text-link" href="#new">Create incident →</a><button class="btn secondary small" type="button" data-action="download-fingerprint">Download fingerprint</button></div></form></div>`;}

function linkPage(){return `${heading('Review a link','See what an address contains before deciding what to do.')}<div class="two-columns"><section class="panel">${privacyLine}<form id="url-form"><div class="field"><label for="suspect-url">Suspicious URL</label><textarea name="url" id="suspect-url" required maxlength="8192" placeholder="Paste the full https://… address" spellcheck="false">${escape(lastUrl?.input || '')}</textarea></div><div class="field"><label for="expected-domain">Domain you expected <span class="muted">(optional)</span></label><input name="expectedDomain" id="expected-domain" maxlength="253" value="${escape(lastUrl?.expected || '')}" placeholder="example.com" autocomplete="off" spellcheck="false"><p class="hint">Hostname only, without https:// or a path. Matching subdomains are allowed.</p></div>${errorBox}<button type="submit" class="btn primary">${icon('link')}Review structure</button></form><div id="url-result">${lastUrl?urlResult():''}</div></section><aside class="note"><h3>We never visit the link</h3><p>This tool checks the text of the address. It has no malware scanner, domain reputation feed, or breach database.</p><h3>No warnings ≠ safe</h3><p>A malicious site can use HTTPS and an ordinary domain. Open a service’s official app or type an address you already trust.</p><a href="#new" class="text-link">Record a suspicious message →</a></aside></div>`;}
function urlResult(){const result=lastUrl.result;return `<div class="result"><h3>Destination hostname</h3><code class="digest">${escape(result.hostname || 'No HTTP(S) hostname')}</code><p class="hint">The hostname identifies the destination; words elsewhere in the URL do not.</p>${result.findings.map(f=>`<div class="finding"><h3><span class="badge ${f.level==='info'?'neutral':'warning'}">${f.level==='info'?'Observation':'Review'}</span>${escape(f.title)}</h3><p>${escape(f.detail)}</p></div>`).join('')}<p class="hint">${escape(result.limitations)}</p><div class="actions result"><button class="btn secondary" data-action="url-case">Create an incident from this review</button></div></div>`;}

function casesPage(){return `${heading('Incident cases','Keep evidence, context, and response steps in one place.',newButton)}<div class="alert">${vaultRaw?'Changes stay in this session until you save the encrypted vault again.':'Cases stay in this session. Save an encrypted vault or backup before closing the page.'} <a href="#vault">Manage storage</a></div><section class="panel">${workspace.cases.length?caseRows([...workspace.cases].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))):emptyCases()}</section>`;}
function caseForm(item){const edit=Boolean(item);return `${heading(edit?'Edit incident':'New incident','Record what you know. Leave uncertainty in the notes.')}<div class="two-columns"><section class="panel"><form id="case-form" ${edit?`data-id="${escape(item.id)}"`:''}><div class="field"><label for="case-title">Incident title</label><input id="case-title" name="title" required maxlength="200" value="${escape(item?.title)}" placeholder="e.g. An account using my name"></div><div class="field"><label for="case-type">What happened?</label><select id="case-type" name="type" ${edit?'disabled':''}>${TYPES.map(t=>`<option value="${t.id}" ${item?.type===t.id?'selected':''}>${t.label}</option>`).join('')}</select>${edit?'<p class="hint">The category stays fixed so the recorded response history keeps its meaning.</p>':''}</div><div class="field"><label for="case-source">Source URL <span class="muted">(optional)</span></label><input id="case-source" name="sourceUrl" type="url" maxlength="2048" value="${escape(item?.sourceUrl)}" placeholder="https://example.com/post"></div><div class="field"><label for="case-summary">What do you know so far? <span class="muted">(optional)</span></label><textarea id="case-summary" name="summary" maxlength="10000" placeholder="What you observed, when it happened, and what still needs checking…">${escape(item?.summary)}</textarea></div>${errorBox}<div class="actions"><button class="btn primary" type="submit">${edit?'Save changes':'Create incident'}</button><a href="${edit?'#case/'+encodeURIComponent(item.id):'#cases'}" class="btn secondary">Cancel</a></div></form></section><aside class="note"><h3>Keep it factual</h3><p>Separate what you observed from what you suspect. Save dates, original messages, and the source of each file.</p><h3>Leave secrets out</h3><p>Do not put passwords, access tokens, recovery codes, or unnecessary personal information in a case.</p><p>These notes are unencrypted in memory while the workspace is open. Save an encrypted backup when you finish.</p></aside></div>`;}
function caseDetail(item){if(!item)return `${heading('Incident not found','It may be in a locked vault or a different session.')}<a href="#vault" class="btn">Open vault</a>`;const steps=PLAYBOOKS[item.type];return `<a class="back-link" href="#cases">← All incidents</a>${heading(escape(item.title),escape(typeLabel(item.type)),`<div class="actions"><a class="btn secondary small" href="#edit/${encodeURIComponent(item.id)}">Edit details</a><button class="btn small" data-action="report" data-id="${escape(item.id)}">${icon('download')}Export report</button></div>`)}<div class="two-columns"><div class="stack"><section class="panel"><h2>Incident record</h2><p class="case-summary">${escape(item.summary || 'No summary recorded yet.')}</p><dl class="facts"><dt>Created</dt><dd>${escape(date(item.createdAt))}</dd><dt>Updated</dt><dd>${escape(date(item.updatedAt))}</dd><dt>Source</dt><dd>${escape(item.sourceUrl || 'Not recorded')}</dd></dl><div class="field"><label for="case-status">Case status</label><select id="case-status" data-case="${escape(item.id)}">${['open','in-progress','resolved'].map(s=>`<option value="${s}" ${s===item.status?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><p class="hint">Status is your record of progress, not an independent safety assessment.</p></div></section><section class="panel"><div class="section-heading"><h2>Evidence records</h2><a href="#evidence" class="text-link">Add file →</a></div>${item.evidence.length?item.evidence.map(e=>`<div class="evidence-row"><h3>${escape(e.name)}</h3><code class="digest">${e.sha256}</code><p>${e.size.toLocaleString()} bytes · Hashed ${escape(date(e.hashedAt))}</p><p>Source: ${escape(e.sourceUrl || 'Not recorded')}</p><p>${escape(e.notes || 'No acquisition notes.')}</p></div>`).join(''):'<p class="subtext">No fingerprints attached. Keep original files separately; this workspace stores records only.</p>'}</section></div><aside class="stack"><section class="panel"><h2>Your response plan</h2><p class="progress-label">${item.completedSteps.length} of ${steps.length} steps recorded</p><ul class="checklist">${steps.map(step=>`<li><label><input type="checkbox" data-case="${escape(item.id)}" data-step="${step.id}" ${item.completedSteps.includes(step.id)?'checked':''}><strong>${escape(step.title)}</strong></label><p>${escape(step.detail)}</p>${external(step.url,'Official guidance')}</li>`).join('')}</ul></section><div><p class="report-note">Reports include your notes and source URLs as plain text. Review for personal information before sharing. Completing steps does not certify recovery.</p><button class="text-link" data-action="delete" data-id="${escape(item.id)}">Delete this incident</button></div></aside></div>`;}

function vault(){return `${heading('Vault & privacy','Your workspace is yours to save, unlock, export, or erase.')}<div class="alert">${workspace.cases.length} incident${workspace.cases.length===1?'':'s'} in this session. ${dirty()?'You have unsaved changes.':savedSnapshot?'This session matches the last saved or opened archive.':'Nothing is automatically saved.'}</div><div class="two-columns"><div class="stack"><section class="panel"><h2>Save this workspace</h2><p class="subtext">Encrypt the case records with a passphrase. Store them in this browser or download a portable backup.</p><form id="save-form"><div class="field result"><label for="save-password">Passphrase</label><input id="save-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required><p class="hint">At least 12 characters. A long, unique passphrase is best. There is no recovery service.</p></div><div class="field"><label for="confirm-password">Repeat passphrase</label><input id="confirm-password" name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="1024" required></div>${errorBox}<div class="actions"><button class="btn primary" name="mode" value="local" ${storageAvailable?'':'disabled'}>Save encrypted vault</button><button class="btn secondary" name="mode" value="download">Download encrypted backup</button></div><p class="hint">Original media files are not included. Save a backup before clearing browser data.</p></form></section><section class="panel"><h2>Unlock or restore</h2><form id="unlock-form"><div class="field"><label for="archive-file">Encrypted backup <span class="muted">(optional)</span></label><input type="file" id="archive-file" name="archive" accept=".json,application/json"><p class="hint">Select a backup, or leave blank to unlock ${vaultRaw?'the vault saved in this browser.':'a saved browser vault (none found yet).'}</p></div><div class="field"><label for="unlock-password">Archive passphrase</label><input id="unlock-password" name="password" type="password" required minlength="12" maxlength="1024" autocomplete="current-password"></div>${errorBox}<button class="btn" type="submit">${icon('lock')}Unlock workspace</button><p class="hint">Restoring replaces the session after confirmation. A wrong passphrase or damaged file leaves it unchanged.</p></form></section></div><aside class="stack"><div class="note">${icon('lock')}<h3>On your device, by default</h3><ul class="vault-list"><li>No accounts, analytics, or evidence uploads.</li><li>Encryption: AES-256-GCM with a key derived from your passphrase using PBKDF2-SHA256 (600,000 iterations).</li><li>Passphrases and encryption keys are not saved.</li><li>Records are readable in memory while unlocked. Encryption cannot protect a compromised device or browser.</li></ul></div><section><h3>Close your workspace</h3><p class="subtext">Locking clears records and pending results from this tab. Your encrypted browser vault stays saved.</p><div class="actions result"><button class="btn secondary" data-action="lock">Lock & clear session</button></div></section><section><h3>Remove saved data</h3><p class="subtext">Delete the encrypted vault from this browser. Downloaded backups and current session records are unaffected.</p><div class="actions result"><button class="btn danger small" data-action="erase-vault" ${vaultRaw?'':'disabled'}>Delete saved vault</button></div></section></aside></div>`;}

const resources=[
 ['Someone is pretending to be you','Preserve the profile URL and messages. Use the affected platform’s impersonation reporting route. Verify unexpected requests using a number you already know.','https://consumer.ftc.gov/articles/scammers-use-fake-emergencies-steal-your-money','FTC · Impersonation and emergency scams'],
 ['A recording may be synthetic','Preserve the original, record its source and transformations, and confirm the surrounding context. Low quality alone does not establish manipulation.','https://www.nist.gov/document/deepfake-trifold-version','NIST · Examining deepfakes'],
 ['An account or system was compromised','Contain ongoing access, preserve relevant evidence, and recover through the organization’s incident process or the provider’s official recovery flow.','https://www.cisa.gov/stopransomware/ransomware-guide','CISA · Incident response guidance'],
 ['You need an incident response process','Use a documented process for analysis, containment, recovery, and follow-up. Organization and jurisdiction requirements vary.','https://www.cisa.gov/sites/default/files/publications/Cybersecurity_Incident_Vulnerability_Response_Playbooks_508C.pdf','CISA · Response playbooks (PDF)'],
 ['Report internet crime in the US','The FBI’s Internet Crime Complaint Center accepts internet-crime reports. This is a US route; elsewhere use the appropriate local authority.','https://www.ic3.gov/','FBI IC3 · US reporting'],
 ['Understand provenance','Content Credentials can describe provenance and modifications. Valid credentials do not prove truth; absent credentials do not prove a fake.','https://spec.c2pa.org/specifications/specifications/2.4/security/Harms_Modelling.html','C2PA · Harms and limitations'],
];
function library(){return `${heading('Response library','Practical guidance, with the source and the limits attached.')}<p class="library-intro">You don’t need to prove a deepfake to pause a suspicious request.</p><div class="alert">If someone demands an urgent payment or secret action, stop and verify through a separate, trusted channel. If there is immediate physical danger, contact local emergency services.</div><div class="resource-list">${resources.map(([title,body,url,label])=>`<article class="resource"><h3>${title}</h3><p>${body}</p>${external(url,label)}</article>`).join('')}</div><section class="result"><h2>How to read our results</h2><div class="resource-list"><article class="resource"><h3>File fingerprints</h3><p>A SHA-256 fingerprint helps compare exact bytes. It does not prove identity, origin, or truth. Hashing time comes from your device.</p></article><article class="resource"><h3>URL structure</h3><p>Warnings describe the address, not the site’s reputation. A legitimate domain can be compromised. A URL with no warnings may still be malicious.</p></article><article class="resource"><h3>AI detection</h3><p>This release does not run an automated deepfake detector or verify C2PA signatures. We do not invent probability scores. Independent context checks remain essential.</p>${external('https://www.ftc.gov/policy/advocacy-research/tech-at-ftc/2024/04/approaches-address-ai-enabled-voice-cloning','FTC · No single solution')}</article><article class="resource"><h3>Privacy & source</h3><p>The tools process data on your device. Hosting providers receive ordinary page requests; external resources open only when you choose them. Source code is MIT licensed and includes setup and testing instructions.</p><a href="./usualcybersec-source.zip" download>Download complete source ↗</a></article></div><p class="hint">Guidance reviewed 22 October 2026. External sources may change. This app neither submits reports nor contacts anyone for you.</p></section>`;}

function render(){const raw=location.hash.slice(1)||'overview';const [route,encodedId]=raw.split('/');let id;try{id=decodeURIComponent(encodedId||'');}catch{id='';}const active=['new','case','edit'].includes(route)?'cases':routes.some(r=>r[0]===route)?route:'overview';$('#navigation').innerHTML=routes.map(([key,label,i])=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');$('#route-label').textContent=routes.find(r=>r[0]===active)[1];document.title=`${$('#route-label').textContent} · usualCyberSec`;const views={overview,evidence,link:linkPage,cases:casesPage,new:()=>caseForm(),case:()=>caseDetail(currentCase(id)),edit:()=>currentCase(id)?caseForm(currentCase(id)):caseDetail(null),vault,library};$('#main').innerHTML=(views[route]||overview)();syncStatus();}
function download(content,filename,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function checkSource(source){if(!source)return '';const url=new URL(source);if(!['http:','https:'].includes(url.protocol))throw Error('Source URLs must start with http:// or https://.');return source;}
async function runForm(form, event){const data=new FormData(form);const value=key=>String(data.get(key)||'').trim();if(form.id==='case-form'){const title=value('title');if(!title)throw Error('Give this incident a title.');const sourceUrl=checkSource(value('sourceUrl'));const existing=currentCase(form.dataset.id);if(existing){updateCase(existing.id,item=>{item.title=title;item.summary=value('summary');item.sourceUrl=sourceUrl;});go('case/'+encodeURIComponent(existing.id));}else{const item=createCase({title,type:value('type'),summary:value('summary'),sourceUrl});commit({...workspace,cases:[item,...workspace.cases]});go('case/'+encodeURIComponent(item.id));}notify('Incident saved in this session.');}
  if(form.id==='hash-form'){const file=data.get('file');if(!file?.name)throw Error('Choose a file first.');if(!crypto?.subtle)throw Error('File hashing requires HTTPS or localhost in a supported browser.');const ticket=++operation;const expected=value('expected');const record=await hashFile(file);if(ticket!==operation)return;latestEvidence={record,expected};if($('#hash-result'))$('#hash-result').innerHTML=evidenceResult();notify('Fingerprint created on this device.');}
  if(form.id==='attach-form'){if(!latestEvidence)throw Error('Fingerprint a file before attaching it.');const id=value('caseId');const sourceUrl=checkSource(value('sourceUrl'));updateCase(id,item=>item.evidence.push({...latestEvidence.record,id:crypto.randomUUID(),sourceUrl,notes:value('notes')}));go('case/'+encodeURIComponent(id));notify('Fingerprint attached. Keep the original file separately.');}
  if(form.id==='url-form'){lastUrl={input:value('url'),expected:value('expectedDomain'),result:analyzeUrl(value('url'),value('expectedDomain'))};$('#url-result').innerHTML=urlResult();}
  if(form.id==='save-form'){const password=String(data.get('password'));if(password!==String(data.get('confirm')))throw Error('The passphrases do not match.');const snapshot=JSON.stringify(workspace);const mode=event.submitter?.value || 'local';const baseline=mode==='local'?localStorage.getItem(storageKey):null;if(mode==='local'){const current=baseline;if(current&&(!savedSnapshot||current!==vaultRaw)&&!confirm('Saving replaces the encrypted vault currently stored in this browser. Continue?'))return;}const envelope=await encryptWorkspace(JSON.parse(snapshot),password);const serialized=JSON.stringify(envelope);if(mode==='local'){await saveCiphertext(localStorage,navigator.locks,storageKey,baseline,serialized);vaultRaw=serialized;savedSnapshot=snapshot;vaultChanged=false;notify('Encrypted vault saved in this browser.');}else{download(serialized,'usualcybersec-backup-'+new Date().toISOString().slice(0,10)+'.json');notify('Encrypted backup download started. Verify it is saved before closing.');}form.reset();if(mode==='local'&&location.hash==='#vault')render();else syncStatus();}
  if(form.id==='unlock-form'){const file=data.get('archive');const {raw,fromFile}=await readArchiveInput(file,file?.name?null:localStorage.getItem(storageKey));let decrypted;try{decrypted=await decryptWorkspace(JSON.parse(raw),String(data.get('password')));}catch{throw Error('Cannot unlock this archive. Check the passphrase and use an unmodified usualCyberSec backup. The current session is unchanged.');}if(workspace.cases.length&&!confirm('Replace the current session with this archive? Unsaved session changes will be lost.'))return;commit(decrypted);savedSnapshot=fromFile?null:JSON.stringify(decrypted);if(!fromFile){vaultRaw=raw;vaultChanged=false;}latestEvidence=null;lastUrl=null;operation++;form.reset();go('cases');notify('Workspace unlocked on this device.');}
}
document.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const form=event.target;const buttons=[...form.querySelectorAll('button')];const disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);busy=true;const error=form.querySelector('.error');if(error)error.hidden=true;try{await runForm(form,event);}catch(err){showError(err,form);}finally{busy=false;buttons.forEach((b,i)=>b.disabled=disabled[i]);}});
document.addEventListener('change',event=>{const target=event.target;if(busy){if(target.matches('[data-step],#case-status'))render();return;}try{if(target.matches('[data-step]')){updateCase(target.dataset.case,item=>{item.completedSteps=target.checked?[...item.completedSteps,target.dataset.step]:item.completedSteps.filter(step=>step!==target.dataset.step);});const item=currentCase(target.dataset.case);$('.progress-label').textContent=`${item.completedSteps.length} of ${PLAYBOOKS[item.type].length} steps recorded`;}if(target.id==='case-status'){updateCase(target.dataset.case,item=>item.status=target.value);notify('Status recorded in this session.');}}catch(error){notify(error.message,true);render();}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;if(busy){notify('Wait for the current operation to finish.');return;}const action=button.dataset.action;const id=button.dataset.id;try{if(action==='report'){const item=currentCase(id);download(exportReport(item),'usualcybersec-incident-'+item.id.replace(/[^a-zA-Z0-9-]/g,'').slice(0,36)+'.md','text/markdown');notify('Report download started. Review personal information before sharing.');}if(action==='download-fingerprint'&&latestEvidence)download(JSON.stringify({tool:'usualCyberSec',...latestEvidence.record,limitations:'Identifies matching bytes only. Does not prove authenticity.'},null,2),'usualcybersec-fingerprint.json');if(action==='url-case'&&lastUrl){const item=createCase({title:'Review: '+(lastUrl.result.hostname||'suspicious link'),type:'phishing',sourceUrl:'',summary:'Submitted URL (unvisited): '+lastUrl.input+'\n\n'+lastUrl.result.findings.map(f=>f.title+': '+f.detail).join('\n')+'\n\n'+lastUrl.result.limitations});commit({...workspace,cases:[item,...workspace.cases]});go('case/'+encodeURIComponent(item.id));}if(action==='delete'&&confirm('Delete this incident from the session, including its fingerprint records? Saved backups are unchanged.')){commit({...workspace,cases:workspace.cases.filter(item=>item.id!==id)});go('cases');notify('Incident deleted from this session. Save again to update your vault.');}if(action==='lock'){if((dirty()||latestEvidence||lastUrl)&&!confirm('Clear the session now? Unsaved cases and pending review results will be lost. Saved vaults and downloaded backups remain.'))return;workspace={version:1,cases:[]};savedSnapshot=null;latestEvidence=null;lastUrl=null;operation++;render();notify('Session cleared. Saved encrypted data is unchanged.');}if(action==='erase-vault'&&confirm('Permanently delete the encrypted vault saved in this browser? Download a backup first if you need it.')){await eraseCiphertext(localStorage,navigator.locks,storageKey);vaultRaw=null;vaultChanged=false;savedSnapshot=null;render();notify('Saved browser vault deleted.');}}catch(err){notify(err.message,true);}});
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});
window.addEventListener('beforeunload',event=>{if(dirty()||busy){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',event=>{if(event.key===storageKey){notify('The saved vault changed in another tab. Download a backup before unlocking its latest copy.');vaultChanged=true;syncStatus();}});
render();
if(!storageAvailable)notify('Browser storage is unavailable. Use encrypted backup downloads.',true);
